testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> bool:
	var path_a: String = "res://characters/player.tscn"
	var path_b: String = "res://Characters/Player.tscn"
	return path_a == path_b
",
   "domanda": "`run()` restituisce vero o falso?",
   "spiegazione": "Restituisce `false` perché i testi sono diversi: Godot e i sistemi operativi fanno distinzione tra maiuscole e minuscole (case sensitivity), quindi "characters" e "Characters" non sono la stessa cosa."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var file_path: String = "res://scenes/ui/main_menu.tscn"
	var ext: String = file_path.get_extension()
	return ext
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`get_extension()` estrae l'estensione del file dal percorso, restituendo la stringa `"tscn"`."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var path: String = "characters/enemy.tscn"
	var is_valid_res: bool = path.begins_with("res://")
	return is_valid_res
",
   "domanda": "`run()` restituisce vero o falso?",
   "spiegazione": "Restituisce `false` perché il percorso non inizia con il prefisso obbligatorio `res://`, che identifica la radice dei file di progetto in Godot."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var full_path: String = "res://items/health_potion.tres"
	var file_name: String = full_path.get_file()
	return file_name
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`get_file()` restituisce solo la parte finale del percorso escludendo le cartelle, cioè `"health_potion.tres"`."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var full_path: String = "res://audio/sfx/jump.wav"
	var base_dir: String = full_path.get_base_dir()
	return base_dir
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`get_base_dir()` restituisce la cartella che contiene il file, rimuovendo il nome del file alla fine: `"res://audio/sfx"`."
  }
 ]
